/**
 * Seeded, dependency-free estimators for experiment reports. Every result is a pure function of
 * (data, seed), so a report can be regenerated byte-for-byte from stored trial records.
 */

/** Uniform pseudo-random source in [0, 1). */
export type Random = () => number;

export interface Interval {
  estimate: number | null;
  ci_low: number | null;
  ci_high: number | null;
}

export interface ResampleOptions {
  samples: number;
  alpha?: number;
  random: Random;
}

export interface PermutationResult {
  p_value: number | null;
  exact: boolean;
  mean_difference: number | null;
  samples: number;
}

/** splitmix32: small, fast, and identical across platforms for a given 32-bit seed. */
export function createSeededRandom(seed: number): Random {
  if (!Number.isSafeInteger(seed) || seed < 0 || seed > 0xffffffff)
    throw new Error("seed must be an integer between 0 and 4294967295");
  let state = seed >>> 0;
  return () => {
    state = (state + 0x9e3779b9) | 0;
    let t = state ^ (state >>> 16);
    t = Math.imul(t, 0x21f0aaad);
    t ^= t >>> 15;
    t = Math.imul(t, 0x735a2d97);
    t ^= t >>> 15;
    return (t >>> 0) / 4294967296;
  };
}

/** Derives an independent stream for a labelled sub-analysis without consuming the parent. */
export function deriveSeed(seed: number, label: string): number {
  let hash = seed >>> 0;
  for (const codePoint of label) {
    hash ^= codePoint.codePointAt(0) ?? 0;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash;
}

/** Fisher–Yates shuffle on a copy; the input is never mutated. */
export function shuffle<T>(items: readonly T[], random: Random): T[] {
  const copy = [...items];
  for (let index = copy.length - 1; index > 0; index--) {
    const swap = Math.floor(random() * (index + 1));
    [copy[index], copy[swap]] = [copy[swap], copy[index]];
  }
  return copy;
}

function finite(values: readonly number[]): number[] {
  return values.filter((value) => Number.isFinite(value));
}

export function mean(values: readonly number[]): number | null {
  const data = finite(values);
  if (data.length === 0) return null;
  return data.reduce((total, value) => total + value, 0) / data.length;
}

/** Type-7 (linear interpolation) quantile on an ascending array. */
export function quantile(sorted: readonly number[], probability: number): number | null {
  if (sorted.length === 0) return null;
  if (probability <= 0) return sorted[0];
  if (probability >= 1) return sorted[sorted.length - 1];
  const position = (sorted.length - 1) * probability;
  const lower = Math.floor(position);
  const upper = Math.ceil(position);
  if (lower === upper) return sorted[lower];
  return sorted[lower] + (sorted[upper] - sorted[lower]) * (position - lower);
}

export function median(values: readonly number[]): number | null {
  return quantile(
    finite(values).sort((left, right) => left - right),
    0.5,
  );
}

/** Sample standard deviation (n − 1); null for fewer than two observations. */
export function standardDeviation(values: readonly number[]): number | null {
  const data = finite(values);
  if (data.length < 2) return null;
  const centre = mean(data) as number;
  const squares = data.reduce((total, value) => total + (value - centre) ** 2, 0);
  return Math.sqrt(squares / (data.length - 1));
}

/**
 * Inverse of the standard normal CDF (Acklam's rational approximation, relative error below
 * 1.15e-9), followed by one Halley refinement step.
 */
export function normalQuantile(probability: number): number {
  if (!(probability > 0 && probability < 1)) throw new Error("probability must lie in (0, 1)");
  if (probability === 0.5) return 0;
  const a = [
    -3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2,
    -3.066479806614716e1, 2.506628277459239,
  ];
  const b = [
    -5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1,
    -1.328068155288572e1,
  ];
  const c = [
    -7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734,
    4.374664141464968, 2.938163982698783,
  ];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
  const low = 0.02425;
  let x: number;
  if (probability < low) {
    const q = Math.sqrt(-2 * Math.log(probability));
    x =
      (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
  } else if (probability <= 1 - low) {
    const q = probability - 0.5;
    const r = q * q;
    x =
      ((((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q) /
      (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1);
  } else {
    const q = Math.sqrt(-2 * Math.log(1 - probability));
    x =
      -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) /
      ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
  }
  const error = normalCdf(x) - probability;
  const density = Math.exp(-(x * x) / 2) / Math.sqrt(2 * Math.PI);
  const step = error / density;
  return x - step / (1 + (x * step) / 2);
}

/** Standard normal CDF via a complementary error function approximation (Numerical Recipes erfc). */
export function normalCdf(value: number): number {
  if (value === 0) return 0.5;
  const z = Math.abs(value) / Math.SQRT2;
  const t = 1 / (1 + 0.5 * z);
  const polynomial =
    -z * z -
    1.26551223 +
    t *
      (1.00002368 +
        t *
          (0.37409196 +
            t *
              (0.09678418 +
                t *
                  (-0.18628806 +
                    t *
                      (0.27886807 +
                        t *
                          (-1.13520398 +
                            t * (1.48851587 + t * (-0.82215223 + t * 0.17087277))))))));
  const erfc = t * Math.exp(polynomial);
  const tail = erfc / 2;
  return value >= 0 ? 1 - tail : tail;
}

/** Wilson score interval for a binomial proportion. */
export function wilsonInterval(successes: number, trials: number, alpha = 0.05): Interval {
  if (!Number.isInteger(successes) || !Number.isInteger(trials) || successes < 0)
    throw new Error("successes and trials must be non-negative integers");
  if (successes > trials) throw new Error("successes cannot exceed trials");
  if (trials === 0) return { estimate: null, ci_low: null, ci_high: null };
  const z = normalQuantile(1 - alpha / 2);
  const proportion = successes / trials;
  const denominator = 1 + (z * z) / trials;
  const centre = (proportion + (z * z) / (2 * trials)) / denominator;
  const spread =
    (z * Math.sqrt((proportion * (1 - proportion)) / trials + (z * z) / (4 * trials * trials))) /
    denominator;
  return {
    estimate: proportion,
    ci_low: successes === 0 ? 0 : Math.max(0, centre - spread),
    ci_high: successes === trials ? 1 : Math.min(1, centre + spread),
  };
}

/** Percentile bootstrap interval for the mean. */
export function bootstrapMeanInterval(
  values: readonly number[],
  { samples, alpha = 0.05, random }: ResampleOptions,
): Interval {
  const data = finite(values);
  if (data.length === 0) return { estimate: null, ci_low: null, ci_high: null };
  const estimate = mean(data) as number;
  if (data.length === 1) return { estimate, ci_low: null, ci_high: null };
  const means = new Array<number>(samples);
  for (let sample = 0; sample < samples; sample++) {
    let total = 0;
    for (let draw = 0; draw < data.length; draw++)
      total += data[Math.floor(random() * data.length)];
    means[sample] = total / data.length;
  }
  means.sort((left, right) => left - right);
  return {
    estimate,
    ci_low: quantile(means, alpha / 2),
    ci_high: quantile(means, 1 - alpha / 2),
  };
}

const EXACT_PERMUTATION_LIMIT = 16;

/**
 * Two-sided paired test on the mean of matched differences by sign flipping. Exact enumeration
 * for up to 16 pairs; otherwise Monte Carlo with the add-one correction so p is never 0.
 */
export function pairedPermutationTest(
  differences: readonly number[],
  { samples, random }: { samples: number; random: Random },
): PermutationResult {
  const data = finite(differences);
  if (data.length === 0) return { p_value: null, exact: true, mean_difference: null, samples: 0 };
  const observed = Math.abs(data.reduce((total, value) => total + value, 0));
  const tolerance = 1e-12 * Math.max(1, observed);
  if (data.every((value) => value === 0))
    return { p_value: 1, exact: true, mean_difference: 0, samples: 0 };
  if (data.length <= EXACT_PERMUTATION_LIMIT) {
    const total = 2 ** data.length;
    let extreme = 0;
    for (let mask = 0; mask < total; mask++) {
      let sum = 0;
      for (let index = 0; index < data.length; index++)
        sum += (mask >> index) & 1 ? -data[index] : data[index];
      if (Math.abs(sum) + tolerance >= observed) extreme++;
    }
    return {
      p_value: extreme / total,
      exact: true,
      mean_difference: mean(data),
      samples: total,
    };
  }
  let extreme = 0;
  for (let sample = 0; sample < samples; sample++) {
    let sum = 0;
    for (const value of data) sum += random() < 0.5 ? -value : value;
    if (Math.abs(sum) + tolerance >= observed) extreme++;
  }
  return {
    p_value: (extreme + 1) / (samples + 1),
    exact: false,
    mean_difference: data.reduce((total, value) => total + value, 0) / data.length,
    samples,
  };
}

/** Two-sided Monte Carlo permutation test on the difference of means of two independent samples. */
export function unpairedPermutationTest(
  left: readonly number[],
  right: readonly number[],
  { samples, random }: { samples: number; random: Random },
): PermutationResult {
  const a = finite(left);
  const b = finite(right);
  if (a.length === 0 || b.length === 0)
    return { p_value: null, exact: false, mean_difference: null, samples: 0 };
  const observed = (mean(a) as number) - (mean(b) as number);
  const pooled = [...a, ...b];
  const tolerance = 1e-12 * Math.max(1, Math.abs(observed));
  let extreme = 0;
  for (let sample = 0; sample < samples; sample++) {
    const permuted = shuffle(pooled, random);
    let sumA = 0;
    for (let index = 0; index < a.length; index++) sumA += permuted[index];
    const sumB = pooled.reduce((total, value) => total + value, 0) - sumA;
    const difference = sumA / a.length - sumB / b.length;
    if (Math.abs(difference) + tolerance >= Math.abs(observed)) extreme++;
  }
  return {
    p_value: (extreme + 1) / (samples + 1),
    exact: false,
    mean_difference: observed,
    samples,
  };
}

/**
 * Exact two-sided McNemar test on discordant pairs: `armOnly` pairs where only the treatment
 * passed and `controlOnly` pairs where only the control passed.
 */
export function mcnemarExactTest(armOnly: number, controlOnly: number): { p_value: number } {
  if (
    !Number.isInteger(armOnly) ||
    !Number.isInteger(controlOnly) ||
    armOnly < 0 ||
    controlOnly < 0
  )
    throw new Error("discordant counts must be non-negative integers");
  const n = armOnly + controlOnly;
  if (n === 0) return { p_value: 1 };
  const k = Math.min(armOnly, controlOnly);
  // Binomial(n, 1/2) lower tail in log space to stay finite for large n.
  let logTerm = -n * Math.LN2;
  let logTail = logTerm;
  for (let i = 1; i <= k; i++) {
    logTerm += Math.log((n - i + 1) / i);
    logTail = logSumExp(logTail, logTerm);
  }
  return { p_value: Math.min(1, 2 * Math.exp(logTail)) };
}

function logSumExp(left: number, right: number): number {
  const larger = Math.max(left, right);
  return larger + Math.log(Math.exp(left - larger) + Math.exp(right - larger));
}

/**
 * Unbiased pass@k estimator (Chen et al., 2021): the probability that at least one of k
 * samples drawn without replacement from n attempts with c successes passes.
 */
export function passAtK(attempts: number, successes: number, k: number): number | null {
  if (![attempts, successes, k].every((value) => Number.isInteger(value) && value >= 0))
    throw new Error("pass@k arguments must be non-negative integers");
  if (successes > attempts) throw new Error("successes cannot exceed attempts");
  if (k < 1 || k > attempts) return null;
  if (attempts - successes < k) return 1;
  let product = 1;
  for (let i = attempts - successes + 1; i <= attempts; i++) product *= 1 - k / i;
  return 1 - product;
}

/** Cohen's kappa between two raters' categorical labels over the same items. */
export function cohensKappa(
  first: readonly string[],
  second: readonly string[],
): { kappa: number | null; observed_agreement: number | null; n: number } {
  if (first.length !== second.length) throw new Error("rater label arrays must align");
  const n = first.length;
  if (n === 0) return { kappa: null, observed_agreement: null, n };
  const categories = new Set([...first, ...second]);
  let agreements = 0;
  for (let index = 0; index < n; index++) if (first[index] === second[index]) agreements++;
  const observed = agreements / n;
  let expected = 0;
  for (const category of categories) {
    const firstShare = first.filter((label) => label === category).length / n;
    const secondShare = second.filter((label) => label === category).length / n;
    expected += firstShare * secondShare;
  }
  if (expected >= 1) return { kappa: observed >= 1 ? 1 : null, observed_agreement: observed, n };
  return { kappa: (observed - expected) / (1 - expected), observed_agreement: observed, n };
}

/** Holm–Bonferroni step-down adjustment; null entries are passed through and not counted. */
export function holmBonferroni(pValues: readonly (number | null)[]): (number | null)[] {
  const indexed = pValues
    .map((value, index) => ({ value, index }))
    .filter((entry): entry is { value: number; index: number } => entry.value !== null)
    .sort((left, right) => left.value - right.value);
  const adjusted: (number | null)[] = pValues.map(() => null);
  const m = indexed.length;
  let running = 0;
  indexed.forEach((entry, rank) => {
    running = Math.max(running, Math.min(1, (m - rank) * entry.value));
    adjusted[entry.index] = running;
  });
  return adjusted;
}

/** Cliff's delta: P(a > b) − P(a < b) over all cross pairs; a scale-free ordinal effect size. */
export function cliffsDelta(left: readonly number[], right: readonly number[]): number | null {
  const a = finite(left);
  const b = finite(right);
  if (a.length === 0 || b.length === 0) return null;
  let greater = 0;
  let less = 0;
  for (const x of a)
    for (const y of b) {
      if (x > y) greater++;
      else if (x < y) less++;
    }
  return (greater - less) / (a.length * b.length);
}

/**
 * Percentile bootstrap interval for a difference of means: paired resampling of matched pairs
 * (left[i] − right[i]) or independent resampling of two samples.
 */
export function bootstrapDifferenceInterval(
  left: readonly number[],
  right: readonly number[],
  { samples, alpha = 0.05, random, paired }: ResampleOptions & { paired: boolean },
): Interval {
  if (paired) {
    if (left.length !== right.length) throw new Error("paired samples must align");
    const differences = left.map((value, index) => value - right[index]);
    return bootstrapMeanInterval(differences, { samples, alpha, random });
  }
  const a = finite(left);
  const b = finite(right);
  if (a.length === 0 || b.length === 0) return { estimate: null, ci_low: null, ci_high: null };
  const estimate = (mean(a) as number) - (mean(b) as number);
  const draws = new Array<number>(samples);
  for (let sample = 0; sample < samples; sample++) {
    let sumA = 0;
    for (let draw = 0; draw < a.length; draw++) sumA += a[Math.floor(random() * a.length)];
    let sumB = 0;
    for (let draw = 0; draw < b.length; draw++) sumB += b[Math.floor(random() * b.length)];
    draws[sample] = sumA / a.length - sumB / b.length;
  }
  draws.sort((x, y) => x - y);
  return { estimate, ci_low: quantile(draws, alpha / 2), ci_high: quantile(draws, 1 - alpha / 2) };
}
